                s = s.Replace("Surely not! Such a brightly coloured hairpiece would only\r\nserve to make the inspector more noticeable.", "Certainement point ! Un postiche d'une teinte aussi vive n'aurait\r\nfait que rendre l'inspecteur d'autant plus voyant.");
                s = s.Replace("Yes, that's quite true.\r\nIt would definitely have made him stand out in a crowd.\r\nExcept, that is...in a crowd of gentlemen from the\r\nRed-Headed League.", "Oui, c'est tout à fait vrai.\r\nCela l'aurait indubitablement fait ressortir dans la foule.\r\nSauf, bien sûr... au milieu d'un rassemblement de la\r\nLigue des Rouquins.");
                s = s.Replace("The, the Red-Headed League?", "La, la Ligue des Rouquins ?");
                s = s.Replace("So...you'd already worked it out.", "Ainsi... tu l'avais déjà compris.");
                s = s.Replace("What on earth is this all about?\r\nIs there such an extraordinary league of gentlemen?", "De quoi s'agit-il au juste, grand Dieu ?\r\nExiste-t-il véritablement une telle et insolite congrégation ?");
                s = s.Replace("The Red-Headed League is currently under investigation\r\nfor a grand deception.", "La Ligue des Rouquins fait actuellement l'objet d'une enquête\r\npour escroquerie de grande envergure.");
                s = s.Replace("A deception of what nature, Counsel?", "Une escroquerie de quelle nature, Maître ?");
                s = s.Replace("They've been targeting red-headed men across all of\r\nLondon and tricking them out of small sums of money.\r\nTwo men were arrested for the misdemeanour only\r\nyesterday, in fact.", "Ils ont ciblé des hommes roux dans tout Londres pour leur soutirer\r\nde coquettes sommes d'argent.\r\nDeux hommes ont été appréhendés pour ce délit hier même,\r\nen réalité.");
                s = s.Replace("My Lord!\r\nThe defence calls for those two men to be summoned at\r\nonce!", "Votre Honneur !\r\nLa défense demande la convocation immédiate de ces deux\r\nhommes !");
                s = s.Replace("T-Two red-heads?!", "D-Deux rouquins ?!");
                s = s.Replace("Inspector Gregson clearly infiltrated the Red-Headed\r\nLeague using this hairpiece.\r\nSo it's very likely that he had direct contact with these\r\ncriminals.\r\nAnd it's quite possible that such contact led to...more\r\nserious events.", "L'inspecteur Gregson a manifestement infiltré la Ligue des\r\nRouquins au moyen de ce postiche.\r\nIl est donc fort probable qu'il ait été en contact direct avec\r\nces malfaiteurs.\r\nEt il est tout à fait possible qu'un tel contact ait mené à... des\r\névénements bien plus graves.");
                s = s.Replace("I concur that we cannot in good conscience leave this new\r\navenue unexplored.", "Je conviens que notre conscience nous interdit de laisser cette\r\nnouvelle piste inexplorée.");
                s = s.Replace("Well done, Mr Naruhodo!", "Bien joué, monsieur Naruhodo !");
                s = s.Replace("Well...it's another possible line of enquiry for us at least.\r\nThe prosecution will make immediate arrangements for\r\nthe charged men to appear.", "Bien... voilà au moins une autre piste d'investigation pour nous.\r\nL'accusation prendra immédiatement les dispositions requises\r\npour faire comparaître les prévenus.");
                s = s.Replace("Bring these two Red-Headed League conspirators before\r\nme, Prosecutor Asogi!\r\nAt once, My Lord.\r\nVery good. We will have a thirty-minute recess.\r\nCourt is adjourned!", "Faites comparaître devant moi ces deux conspirateurs de la\r\nLigue des Rouquins, procureur Asogi !\r\nÀ l'instant, Votre Honneur.\r\nFort bien. Nous suspendons l'audience pour trente minutes.\r\nLa séance est levée !");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c103_0070_eng#6"] = (en) => {
                string s = en;
                s = s.Replace("That will do!", "Cela suffit !");
                s = s.Replace("I believe I have heard quite enough evidence to form an\r\nunbiased opinion.", "J'estime avoir entendu suffisamment d'éléments pour me forger une\r\nopinion impartiale.");
                s = s.Replace("As this is a closed trial, the findings of this court will not\r\nbe disclosed to the public.", "S'agissant d'un procès à huis clos, les conclusions de ce tribunal\r\nne seront point divulguées au public.");
                s = s.Replace("However, this will be the very last time the Reaper stands\r\nin this or any other courtroom.", "Toutefois, ce sera la toute dernière fois que le Faucheur comparaîtra\r\ndans cette salle d'audience ou toute autre.");
                s = s.Replace("B-But, My Lord! Wait!", "M-Mais, Votre Honneur ! Attendez !");
                s = s.Replace("Barok van Zieks, in accordance with the findings of this\r\ncourt, I pronounce you...", "Drake Van Peers, conformément aux constatations de ce\r\ntribunal, je vous déclare...");
                s = s.Replace("That is all. Court is adjourned!", "C'est tout. L'audience est levée !");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c104_0000_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("2nd November, 12:33 p.m.\r\n<CNTR><E003 5>The Old Bailey, Defendants' Antechamber", "2 novembre, 12 h 33\r\n<CNTR><E003 5>Old Bailey, antichambre des accusés");
                s = s.Replace("there you are, ", "t'es là, ");
                s = s.Replace("'Oddo!", "'Oddo !");
                s = s.Replace("What kept you, ", "Qu'est-ce qui vous a retenu, ");
                s = s.Replace("my dear fellow?", "mon cher ami ?");
                s = s.Replace("Hello, ", "Bonjour, ");
                s = s.Replace("Mr Sholmes.", "monsieur Sholmes.");
                s = s.Replace("Gina.", "Gina.");
                s = s.Replace("You sure about wot you said in there?", "T'es sûr d'c'que t'as raconté là-dedans ?");
                s = s.Replace("That the boss...you know...actually died the day before?\r\nIt's pretty 'ard to swallow.", "Que l'patron... enfin tu vois... s'rait mort la veille ?\r\nC'est rudement dur à avaler.");
                s = s.Replace("I was shocked by the revelation too, ", "j'ai également été bouleversée par cette révélation, ");
                s = s.Replace("As was I! Possibly more shocked than both of you!", "Tout comme moi ! Davantage sous le choc que vous deux réunis !");
                s = s.Replace("...It's not a competition, Mr Sholmes.", "... Ce n'est pas un concours, monsieur Sholmes.");
                s = s.Replace("(But I was more shocked than all of you put together.)", "(Mais j'étais plus choqué que vous tous réunis.)");
                s = s.Replace("This is the autopsy report in question, is it?", "C'est donc là le rapport d'autopsie en question ?");
                s = s.Replace("Yes. It's strange that there's no time of death noted.", "Oui. Il est étrange qu'aucune heure de décès n'y figure.");
                s = s.Replace("I suppose there's a simple explanation. Or perhaps...it was\r\na deliberate omission.", "J'imagine qu'il y a une explication toute simple. Ou alors... c'était\r\nune omission délibérée.");
                s = s.Replace("Oh dear...\r\nIf it was deliberate...\r\n...it puts me in mind of the last case we worked on...and\r\nDr Sithe.", "Oh ciel...\r\nSi c'était délibéré...\r\n... cela me rappelle notre dernière affaire... et la\r\nDre Pétrie.");
                s = s.Replace("I know. Anyway, it seems that on the day before Lord\r\nvan Zieks discovered his body...\r\n...Inspector Gregson was investigating the Red-Headed\r\nLeague. So perhaps something happened with them.", "Je sais. En tout cas, il semble que la veille du jour où Lord\r\nVan Peers a découvert son corps...\r\n... l'inspecteur Gregson enquêtait sur la Ligue des Rouquins.\r\nIl s'est donc peut-être passé quelque chose avec eux.");
                s = s.Replace("Come to think of it...\r\n...you had trouble with those league men too, didn't you,\r\nMr Sholmes? You were taken in by their trick.", "À bien y réfléchir...\r\n... vous avez eu des ennuis avec les membres de cette ligue vous aussi,\r\nn'est-ce pas, monsieur Sholmes ? Vous vous êtes fait berner par leur ruse.");
                s = s.Replace("No no no!\r\nNaturally, I wasn't ‘taken in’ as you put it.", "Non non non !\r\nNaturellement, je ne me suis point fait « berner », comme vous dites.");
                s = s.Replace("My sleuth-hound interest was merely piqued slightly by\r\nthe rare scent of a weekly four-pound income.", "Mon flair d'enquêteur s'est simplement trouvé émoustillé par\r\nle doux fumet d'une rente hebdomadaire de quatre livres.");
                s = s.Replace("...And that scent masked the underlying scent of\r\ndeception, I suppose.", "... Et ce parfum a masqué l'odeur sous-jacente de la supercherie,\r\nj'imagine.");
                s = s.Replace("The two criminals in question are the pair we saw being\r\narrested yesterday, aren't they?\r\nIn Mr Sholmes's suite, I mean.", "Les deux criminels en question sont ceux que nous avons vus se\r\nfaire arrêter hier, n'est-ce pas ?\r\nDans les appartements de monsieur Sholmes, je veux dire.");
                s = s.Replace("That's right, Sooze! An' it was me wot took 'em in!\r\nThanks to a tip-off by a good, law-abidin' citizen.", "C'est bien ça, Sooze ! Et c'est moi qui les ai cravatés !\r\nGrâce au tuyau d'un honnête citoyen respectueux d'la loi.");
                s = s.Replace("Indeed. Yours truly.", "En effet. Votre humble serviteur.");
                s = s.Replace("(So it's going to be that pair in the witness stand next, is\r\nit?)", "(Ce sont donc ces deux-là qui vont comparaître à la barre à présent ?)");
                s = s.Replace("Something doesn't quite make sense to me, though.", "Il y a pourtant quelque chose qui m'échappe.");
                s = s.Replace("The day before Inspector Gregson was found, you hadn't\r\nhad trouble with the Red-Headed League yet, had you?\r\nWhy would the inspector have been investigating them?", "La veille du jour où l'inspecteur Gregson a été découvert, vous n'aviez\r\npas encore eu d'ennuis avec la Ligue des Rouquins, si ?\r\nPourquoi l'inspecteur aurait-il enquêté sur eux ?");
                s = s.Replace("Well, the likely explanation would be...\r\n...that Gregson's own sleuth-hound interest was piqued\r\nby the rare scent of a weekly four-pound income.", "Eh bien, l'explication la plus plausible serait...\r\n... que le flair de ce bon vieux Gregson a lui aussi été émoustillé\r\npar le doux fumet d'une rente hebdomadaire de quatre livres.");
                s = s.Replace("Don't tar 'im wiv the same brush as you, Sholmes!", "L'mettez pas dans l'même panier qu'vous, Sholmes !");
                s = s.Replace("Yes, well...\r\nThen there's the whole issue of Inspector Gregson being\r\ninvestigated by Lord van Zieks for some reason.\r\nThe Reaper...the Red-Headed League...\r\nInspector Gregson...Lord van Zieks...\r\n...And Kazuma.\r\n...!\r\nI feel as though he knew we'd arrive at this point\r\nsomehow.", "Oui, eh bien...\r\nIl y a aussi toute cette histoire d'enquête menée par Lord\r\nVan Peers sur l'inspecteur Gregson, pour une raison inconnue.\r\nLe Faucheur... la Ligue des Rouquins...\r\nL'inspecteur Gregson... Lord Van Peers...\r\n... et Kazuma.\r\n... !\r\nJ'ai l'impression qu'il savait que nous en arriverions là.");
                s = s.Replace("Gosh! I, I think you're right...", "Ciel ! Je... je crois que vous avez raison...");
                s = s.Replace("(What's he really trying to achieve here today?)", "(Que cherche-t-il réellement à accomplir aujourd'hui ?)");
                s = s.Replace("All the answers will soon be revealed.\r\n...Observe the time, my dear fellow.\r\nThis recess will be over very shortly.", "Toutes les réponses seront bientôt révélées.\r\n... Regardez l'heure, mon cher ami.\r\nCette suspension d'audience va s'achever sous peu.");
                s = s.Replace("Yes, you're right.", "Oui, vous avez raison.");
                s = s.Replace("(Kazuma was determined that he should be the one to\r\nprosecute this trial.)", "(Kazuma tenait absolument à être celui qui soutiendrait l'accusation.)");
                s = s.Replace("(And he was determined that I should take the defence.)", "(Et il tenait à ce que j'assure la défense.)");
                s = s.Replace("(Just what is it that he's hoping to make me see, I wonder?)", "(Qu'espère-t-il au juste me faire comprendre ?)");
                s = s.Replace("(I get the feeling we're a long way from the end of this\r\ntrial yet...)", "(J'ai la nette impression que nous sommes encore loin de voir le bout\r\nde ce procès...)");
                s = s.Replace("Are you ready then, Miss Susato?", "Êtes-vous prête, mademoiselle Susato ?");
                s = s.Replace("Yes!", "Oui !");
                return s;
            };

